diff --git a/mysql-test/main/deny_revoke_public.result b/mysql-test/main/deny_revoke_public.result
index a82947a61c4b1..62f2fb444ee6d 100644
--- a/mysql-test/main/deny_revoke_public.result
+++ b/mysql-test/main/deny_revoke_public.result
@@ -184,6 +184,34 @@ connect  default, localhost, root,,;
 # UPDATE works again after reconnecting
 UPDATE mysql.global_priv SET Priv=Priv WHERE User='root' AND Host='localhost';
 #
+# MDEV-41343 REVOKE DENY ... FROM PUBLIC bypass via unrelated
+# column-level UPDATE grant on mysql.global_priv
+#
+CREATE USER u@localhost;
+GRANT UPDATE (Host) ON mysql.global_priv TO u@localhost;
+DENY SELECT ON test.t1 TO PUBLIC;
+# Column-level UPDATE is not enough
+connect  con, localhost, u,,;
+REVOKE DENY SELECT ON test.t1 FROM PUBLIC;
+ERROR 42000: SELECT, GRANT command denied to user 'u'@'localhost' for table `test`.`t1`
+disconnect con;
+# Table-level UPDATE with a column-level DENY is not enough
+connection default;
+GRANT UPDATE ON mysql.global_priv TO u@localhost;
+DENY UPDATE (Priv) ON mysql.global_priv TO u@localhost;
+connect  con, localhost, u,,;
+REVOKE DENY SELECT ON test.t1 FROM PUBLIC;
+ERROR 42000: SELECT, GRANT command denied to user 'u'@'localhost' for table `test`.`t1`
+disconnect con;
+# Table-level UPDATE is enough
+connection default;
+REVOKE DENY UPDATE (Priv) ON mysql.global_priv FROM u@localhost;
+connect  con, localhost, u,,;
+REVOKE DENY SELECT ON test.t1 FROM PUBLIC;
+disconnect con;
+connection default;
+DROP USER u@localhost;
+#
 # Cleanup
 #
 DROP PROCEDURE test.p1;
